<script>
 import {onMount,onDestroy} from 'svelte';
 import {api,json} from './lib/api.js';
 import {bytes,allocationBytes,usedPercent} from './lib/storage.js';
 export let onRefresh=()=>{};
 const endpoint='/api/operator/storage';
 let data=null,error='',message='',busy=false,plan=null,confirmation='',backup=false;
 let mountTarget='',operation='grow-filesystem',amount='1',timer=null,polling=false;
 let initial=null,initialDisk='',initialConfirm='';
 $: mounts=(data?.mounts||[]).filter(m=>m.device);
 $: memoryMounts=(data?.mounts||[]).filter(m=>!m.device);
 $: selected=mounts.find(m=>m.target===mountTarget);
 $: running=['queued','running'].includes(data?.job?.state);
 $: persistence=mounts.find(m=>m.target==='/var/prstnt');
 $: available=selected&&(operation==='allocate'?selected.allocation?.available:selected.grow?.available);
 $: reason=selected?(operation==='allocate'?selected.allocation?.reason:selected.grow?.reason):'Select a mount point.';
 function invalidate(){plan=null;confirmation='';backup=false;message=''}
 async function load(){if(busy)return;busy=true;error='';try{data=await api(endpoint);if(!data.mounts.some(m=>m.device&&m.target===mountTarget))mountTarget=data.mounts.find(m=>m.device)?.target||'';initial=await api('/api/storage');initialDisk=initial.candidates?.[0]?.path||''}catch(e){error=e.message}finally{busy=false}}
 onMount(()=>{load();timer=setInterval(async()=>{if(!running||polling)return;polling=true;try{const job=await api(endpoint+'/job');data={...data,job};if(!['queued','running'].includes(job.state)){await load();await onRefresh()}}catch(e){error=e.message}finally{polling=false}},3000)});
 onDestroy(()=>clearInterval(timer));
 async function preview(op=operation,target=mountTarget){if(busy||running)return;busy=true;error='';invalidate();try{const request={operation:op,target};if(op==='allocate')request.add_bytes=allocationBytes(amount);const result=await json(endpoint+'/plan','POST',request);plan=result.plan;message=result.message}catch(e){error=e.message}finally{busy=false}}
 async function execute(){if(!plan||!backup||confirmation!==plan.confirmation||busy||running)return;busy=true;error='';try{const result=await json(endpoint+'/apply','POST',{plan_id:plan.id,confirmation});data={...data,job:result.job};invalidate();message='Confirmed operation started. Progress is recorded here even if this page closes.'}catch(e){error=e.message}finally{busy=false}}
 async function provision(){if(!initialDisk||initialConfirm!=='PROVISION '+initialDisk||busy)return;busy=true;error='';try{const result=await json('/api/storage/provision','POST',{device:initialDisk,confirm:'PROVISION'});initial=result.storage;message='Persistent storage provisioned.';await onRefresh()}catch(e){error=e.message}finally{busy=false;await load()}}
</script>
<div class="page storage-page">
 <div class="page-title"><div><h1>Storage</h1><p>Local disks, mounted filesystems and LVM capacity.</p></div><button class="btn" disabled={busy} on:click={()=>{invalidate();load()}}>Refresh storage</button></div>
 {#if error}<div class="notice warn" role="alert">{error}</div>{/if}
 {#if message}<div class="notice" role="status">{message}</div>{/if}
 {#if !data}<div class="panel"><div class="empty">{busy?'Inspecting local storage...':'Storage information is unavailable.'}</div></div>{:else}
 <div class="cards">
  <div class="panel metric"><div class="label">Persistent storage</div><div class="value">{persistence?bytes(persistence.total_bytes):'Not mounted'}</div><div class="detail">{persistence?bytes(persistence.available_bytes)+' available at /var/prstnt':'Provision persistence before resizing storage.'}</div></div>
  <div class="panel metric"><div class="label">Physical disks</div><div class="value">{data.devices.filter(d=>d.type==='disk').length}</div><div class="detail">Optical and RAM devices are not counted.</div></div>
  <div class="panel metric"><div class="label">LVM volume groups</div><div class="value">{data.lvm.available?data.lvm.vgs.length:'Unavailable'}</div><div class="detail">{data.lvm.available?'Discovered on this appliance.':'Missing tools or discovery failed.'}</div></div>
  <div class="panel metric"><div class="label">Unallocated LVM space</div><div class="value">{data.lvm.available?bytes(data.lvm.vgs.reduce((sum,v)=>sum+Number(v.vg_free),0)):'Unavailable'}</div><div class="detail">Different from unused space inside a filesystem.</div></div>
 </div>
 {#each data.warnings||[] as warning}<div class="notice warn">{warning}</div>{/each}
 <section class="panel"><div class="panel-head"><h2>Mounted filesystems</h2></div><div class="panel-body stack">
 {#each mounts as mount}<article class="filesystem"><div class="mount-heading"><div><strong class="mono">{mount.target}</strong><div class="muted">{mount.device} · {mount.fstype}</div></div><strong>{bytes(mount.available_bytes)} available</strong></div><progress max="100" value={usedPercent(mount)} aria-label={'Used space on '+mount.target}></progress><div class="mount-heading muted"><span>{bytes(mount.used_bytes)} used / {bytes(mount.total_bytes)} usable filesystem capacity</span><span>{bytes(mount.device_bytes)} backing device</span></div>{#if mount.size_warning}<div class="muted">{mount.size_warning}</div>{/if}<div class="actions"><button class="btn small" disabled={busy||running} on:click={()=>{mountTarget=mount.target;operation=mount.allocation?.available?'allocate':'grow-filesystem';invalidate()}}>Manage capacity</button>{#if !mount.allocation?.available&&!mount.grow?.available}<small class="muted">{mount.grow?.reason}</small>{/if}</div></article>{/each}
 {#if !mounts.length}<p class="muted">No block-backed filesystem mounts were reported.</p>{/if}
 </div></section>
 <section class="panel"><div class="panel-head"><h2>Give space to a mount</h2></div><div class="panel-body stack">
 <div class="form-grid"><label class="field"><span>Mount point</span><select bind:value={mountTarget} on:change={invalidate} disabled={busy||running}><option value="">Select a mount</option>{#each mounts as mount}<option value={mount.target}>{mount.target} ({mount.device})</option>{/each}</select></label><label class="field"><span>Capacity operation</span><select bind:value={operation} on:change={invalidate} disabled={busy||running}><option value="grow-filesystem">Grow filesystem into its existing device</option><option value="allocate">Allocate free LVM space and grow filesystem</option></select></label>
 {#if operation==='allocate'}<label class="field"><span>Additional space (GiB)</span><input type="text" inputmode="decimal" bind:value={amount} on:input={invalidate} disabled={busy||running}/><small class="muted">Rounded up to whole LVM extents. The preview shows the exact amount.</small></label>{/if}</div>
 {#if selected?.allocation?.available&&operation==='allocate'}<div class="notice">Volume group <strong>{selected.allocation.vg}</strong> has {bytes(selected.allocation.free_bytes)} unallocated. This does not take space away from other mounts.</div>{/if}
 {#if !available}<div class="notice">{reason||'No supported growth operation is available for this mount.'}</div>{/if}
 <div class="actions"><button class="btn primary" disabled={busy||running||!available} on:click={()=>preview()}>Preview capacity change</button></div>
 <p class="muted">To use a larger virtual disk, enlarge it in the hypervisor first. A containing partition must also be expanded separately. Refresh here, expand an existing LVM physical volume if applicable, then allocate its free space to the chosen mount. Plain ext4/XFS disks use Grow filesystem. No shrinking, repartitioning, new volume creation, or data moves are performed.</p>
 </div></section>
 {#if plan}<section class="panel preview" aria-label="Storage change preview"><div class="panel-head"><h2>Review before applying</h2><span class="spacer"></span><button class="btn small" on:click={invalidate} disabled={busy}>Discard preview</button></div><div class="panel-body stack"><div class="notice warn">{plan.warning}</div><div class="detail-grid"><div class="detail-item"><div class="k">Current capacity</div><div class="v">{bytes(plan.details.current_bytes)}</div></div><div class="detail-item"><div class="k">{plan.details.target_bytes?'Target capacity':'Expanded backing device'}</div><div class="v">{bytes(plan.details.target_bytes??plan.details.device_bytes)}</div></div>{#if plan.details.vg_remaining_bytes!==undefined}<div class="detail-item"><div class="k">Volume group space remaining</div><div class="v">{bytes(plan.details.vg_remaining_bytes)}</div></div>{/if}</div>
 <div class="stack">{#each plan.steps as step}<div><strong>{step.description}</strong><div class="mono muted">{step.tool} {step.args.join(' ')}</div></div>{/each}</div>
 <small class="muted">This preview expires in five minutes. Device identity, mount state and allocation are checked again before any write.</small>
 <label class="storage-check"><input type="checkbox" bind:checked={backup}/><span>I have a current backup and understand that growth is not automatically reversible.</span></label><label class="field"><span>Type {plan.confirmation} to confirm</span><input bind:value={confirmation} autocomplete="off" spellcheck="false"/></label><div class="actions"><button class="btn danger" disabled={busy||running||!backup||confirmation!==plan.confirmation} on:click={execute}>Apply confirmed change</button></div></div></section>{/if}
 <section class="panel"><div class="panel-head"><h2>Volume groups and physical volumes</h2></div><div class="panel-body stack">
 {#if !data.lvm.available}<p class="muted">LVM discovery is unavailable. This does not mean that there are no volume groups.</p>{:else if !data.lvm.vgs.length}<p class="muted">No LVM volume groups are configured. Plain filesystems cannot receive free extents from an LVM group.</p>{:else}
 {#each data.lvm.vgs as group}<article class="filesystem"><strong>{group.vg_name}</strong><div>{bytes(group.vg_size)} total · {bytes(group.vg_free)} unallocated</div>{#each data.lvm.lvs.filter(v=>v.vg_name===group.vg_name) as volume}<div class="mono muted">{volume.lv_path} · {bytes(volume.lv_size)} · {volume.segtype}</div>{/each}</article>{/each}
 {#each data.pv_actions||[] as pv}<article class="filesystem"><strong class="mono">{pv.device}</strong>{#if pv.available}<p>Additional visible capacity can be added to <strong>{pv.vg}</strong>; approximately {bytes(pv.estimated_added_bytes)}.</p><button class="btn" disabled={busy||running} on:click={()=>preview('grow-pv',pv.device)}>Preview LVM physical-volume expansion</button>{:else}<p class="muted">{pv.reason}</p>{/if}</article>{/each}
 {/if}</div></section>
 <section class="panel"><div class="panel-head"><h2>Disk and block-device inventory</h2></div><div class="panel-body stack">{#each data.devices as disk}<div class="disk-row"><div><strong class="mono">{disk.path}</strong><div class="muted">{disk.model||disk.type}{disk.serial?' · '+disk.serial:''}</div></div><div>{bytes(disk.size)}<div class="muted">{disk.fstype||'No filesystem reported'}{disk.ro?' · read-only':''}</div></div></div>{/each}</div></section>
 <details class="panel"><summary>RAM, virtual and non-block mounts</summary><div class="panel-body stack">{#each memoryMounts as mount}<div class="disk-row"><span class="mono">{mount.target}</span><span>{mount.fstype} · {bytes(mount.available_bytes)} available</span></div>{/each}<p class="muted">These mounts are not disk-allocation targets. Memory-backed filesystems do not gain disk space through LVM.</p></div></details>
 {#if initial&&!initial.mounted}<details class="panel"><summary>Initial persistent-storage provisioning</summary><div class="panel-body stack"><div class="notice warn">This separate first-run operation erases an unused whole disk and formats it as appliance persistence. It is not an expansion operation.</div>{#if initial.candidates?.length}<label class="field"><span>Unused whole disk</span><select bind:value={initialDisk} on:change={()=>initialConfirm=''}>{#each initial.candidates as disk}<option value={disk.path}>{disk.path} · {bytes(disk.size)}</option>{/each}</select></label><label class="field"><span>Type PROVISION {initialDisk}</span><input bind:value={initialConfirm}/></label><button class="btn danger" disabled={busy||running||initial.formatter_available===false||initialConfirm!=='PROVISION '+initialDisk} on:click={provision}>Erase and provision selected disk</button>{:else}<p>No unused writable whole disk is available.</p>{/if}</div></details>{/if}
 <section class="panel"><div class="panel-head"><h2>Last storage operation</h2><span class="pill">{data.job?.state||'idle'}</span></div><div class="panel-body stack"><div role="status">{data.job?.message||'No changes requested.'}</div>{#if data.job?.recovery}<div class="notice warn">{data.job.recovery}</div>{/if}{#each data.job?.steps||[] as step}<div><strong>{step.description}: {step.state}</strong>{#if step.output}<pre class="code">{step.output}</pre>{/if}</div>{/each}{#if data.job?.metadata_backup}<div class="muted">LVM metadata backup: <span class="mono">{data.job.metadata_backup}</span></div>{/if}</div></section>
 {/if}
</div>
<style>
 .storage-page{display:grid;gap:1rem;min-width:0}.storage-page .page-title{margin-bottom:0}.storage-page .filesystem{display:grid;gap:.6rem;padding-bottom:1rem;border-bottom:1px solid var(--line)}.filesystem:last-child{border-bottom:0;padding-bottom:0}.mount-heading,.disk-row{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;overflow-wrap:anywhere}.storage-page progress{width:100%;height:.65rem;accent-color:var(--accent)}.disk-row{border-bottom:1px solid var(--line);padding-bottom:.55rem}.storage-page details>summary{cursor:pointer;padding:1rem;font-weight:650}.storage-check{display:flex;align-items:flex-start;gap:.7rem}.storage-check input{width:18px;min-width:18px;min-height:18px;margin-top:.2rem}.preview{border-color:var(--warn)}.storage-page .notice,.storage-page .mono{overflow-wrap:anywhere}.storage-page .actions .btn{white-space:normal}
</style>
